def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    cells = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cells[grid[r][c]].append((r, c))
    for color, pts in cells.items():
        s = set(pts)
        unseen = set(s)
        while unseen:
            seed = unseen.pop()
            comp = {seed}
            stack = [seed]
            while stack:
                r, c = stack.pop()
                for dr in (-1, 1):
                    for dc in (-1, 1):
                        q = (r + dr, c + dc)
                        if q in unseen:
                            unseen.remove(q)
                            comp.add(q)
                            stack.append(q)
            for r, c in comp:
                neighbors = [(rr, cc) for rr, cc in comp if abs(rr-r)==1 and abs(cc-c)==1]
                if len(neighbors) == 1:
                    nr, nc = neighbors[0]
                    dr, dc = r-nr, c-nc
                    rr, cc = r+dr, c+dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == bg:
                            out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out

