def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    cells = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cells[grid[r][c]].append((r, c))
    for color, pts in cells.items():
        s = set(pts)
        for r, c in pts:
            # A terminal pixel has exactly one same-color neighbor in its 8-neighborhood,
            # and that neighbor is diagonal. Continue outward along the diagonal.
            neighbors = [(rr, cc) for rr, cc in s
                         if max(abs(rr-r), abs(cc-c)) == 1]
            if len(neighbors) != 1:
                continue
            nr, nc = neighbors[0]
            if abs(nr-r) != 1 or abs(nc-c) != 1:
                continue
            dr, dc = r-nr, c-nc
            rr, cc = r+dr, c+dc
            while 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] == bg:
                    out[rr][cc] = color
                rr += dr
                cc += dc
    return out
